('recipes/lk-kartoffel-spinat-topf-62385', 'recipes', '{"category": "main", "createdAt": "2026-11-02T21:30:00.000Z", "effort": null, "image": "lk-kartoffel-spinat-topf-62385", "importId": null, "ingredients": [{"amount": 2, "unit": null, "name": "Knoblauchzehen", "raw": "2 Knoblauchzehen", "foodId": null}, {"amount": 125, "unit": "g", "name": "Zwiebeln", "raw": "125 g Zwiebeln", "foodId": null}, {"amount": 800, "unit": "g", "name": "Kartoffeln", "raw": "800 g Kartoffeln", "foodId": null}, {"amount": 1, "unit": "EL", "name": "Öl", "raw": "1 EL Öl", "foodId": null}, {"amount": 1, "unit": "Dose", "name": "Tomaten", "raw": "1 Dose (425 ml) Tomaten", "foodId": null}, {"amount": 2, "unit": null, "name": "Möhren (ca. 185 g)", "raw": "2 Möhren (ca. 185 g)", "foodId": null}, {"amount": 1, "unit": "Dose", "name": "Kichererbsen", "raw": "1 Dose (425 ml) Kichererbsen", "foodId": null}, {"amount": 1, "unit": "Dose", "name": "(400 g) Kokosmilch", "raw": "1 Dose(n) (400 g) Kokosmilch", "foodId": null}, {"amount": 1, "unit": "EL", "name": "rote Thai-Curry-Paste", "raw": "1 EL rote Thai-Curry-Paste", "foodId": null}, {"amount": null, "unit": null, "name": "Salz", "raw": "Salz", "foodId": null}, {"amount": 100, "unit": "g", "name": "Blattspinat", "raw": "100 g Blattspinat", "foodId": null}, {"amount": 5, "unit": "Stiel", "name": "Petersilie", "raw": "5 Stiele Petersilie", "foodId": null}, {"amount": null, "unit": null, "name": "Pfeffer", "raw": "Pfeffer", "foodId": null}, {"amount": null, "unit": null, "name": "Zitronensaft", "raw": "Zitronensaft", "foodId": null}, {"amount": null, "unit": null, "name": "Zucker", "raw": "Zucker", "foodId": null}], "instructions": "Zwiebeln und Knoblauch zerkleinern, Kartoffeln schälen und in Spalten schneiden. Zwiebeln und Knoblauch im Öl andünsten, Kartoffeln kurz mitbraten, Tomaten zugeben und etwa 12 Minuten köcheln lassen.\nMöhren in Stifte schneiden, Kichererbsen abtropfen lassen. Beides mit Kokosmilch und Currypaste zugeben und 5–6 Minuten weiterköcheln.\nSpinat kurz unterrühren, mit Salz, Pfeffer, Zitronensaft und Zucker abschmecken und mit gehackter Petersilie servieren.", "nutrition": {"basis": "portion", "carbs": 55, "fat": 27, "kcal": 515, "protein": 13, "quality": "original"}, "prepMinutes": 35, "servings": 4, "source": "https://www.lecker.de/kartoffel-spinat-topf-62385.html", "tags": "vegetarisch, kartoffel", "title": "Kartoffel-Spinat-Topf", "titleKey": "kartoffel spinat topf", "updatedAt": "2026-11-02T21:30:00.000Z", "version": 1}'::jsonb),
('recipes/lk-gemuese-kartoffel-curry-70868', 'recipes', '{"category": "main", "createdAt": "2026-11-02T21:30:00.000Z", "effort": null, "image": "lk-gemuese-kartoffel-curry-70868", "importId": null, "ingredients": [{"amount": 2, "unit": null, "name": "große Kartoffeln", "raw": "2 große Kartoffeln", "foodId": null}, {"amount": 1, "unit": null, "name": "große Möhre", "raw": "1 große Möhre", "foodId": null}, {"amount": 1, "unit": null, "name": "Zucchini", "raw": "1 Zucchini", "foodId": null}, {"amount": 1, "unit": null, "name": "kleiner Blumenkohl", "raw": "1 kleiner Blumenkohl", "foodId": null}, {"amount": 1, "unit": null, "name": "Zwiebel", "raw": "1 Zwiebel", "foodId": null}, {"amount": 2, "unit": "EL", "name": "Öl", "raw": "2 EL Öl", "foodId": null}, {"amount": null, "unit": null, "name": "Salz", "raw": "Salz", "foodId": null}, {"amount": null, "unit": null, "name": "Pfeffer", "raw": "Pfeffer", "foodId": null}, {"amount": 2, "unit": "EL", "name": "Currypulver", "raw": "2 EL Currypulver", "foodId": null}, {"amount": 1, "unit": "TL", "name": "Mehl", "raw": "1 TL Mehl", "foodId": null}, {"amount": 1, "unit": "Dose", "name": "ungesüßte Kokosmilch", "raw": "1 Dose (à 400 g) ungesüßte Kokosmilch", "foodId": null}, {"amount": 1, "unit": "TL", "name": "Gemüsebrühe (instant)", "raw": "1-2 TL Gemüsebrühe (instant)", "foodId": null}, {"amount": 150, "unit": "g", "name": "TK-Erbsen", "raw": "150 g TK-Erbsen", "foodId": null}, {"amount": 4, "unit": "Stiel", "name": "Koriander oder Petersilie", "raw": "4 Stiele Koriander oder Petersilie", "foodId": null}], "instructions": "Kartoffeln würfeln, Möhre in Stifte, Zucchini und Blumenkohl in Stücke schneiden, Zwiebel fein würfeln.\nZwiebel, Kartoffeln, Möhre und Zucchini im Öl andünsten, mit Curry und Mehl bestäuben, mit Kokosmilch und Wasser ablöschen, Brühe einrühren und den Blumenkohl zugedeckt garen.\nErbsen zugeben, offen weitergaren, abschmecken und mit Kräutern servieren.", "nutrition": {"basis": "portion", "carbs": 35, "fat": 30, "kcal": 452, "protein": 14, "quality": "original"}, "prepMinutes": 30, "servings": 4, "source": "https://www.lecker.de/gemuese-kartoffel-curry-70868.html", "tags": "vegetarisch, kartoffel", "title": "Gemüse-Kartoffel-Curry", "titleKey": "gemuese kartoffel curry", "updatedAt": "2026-11-02T21:30:00.000Z", "version": 1}'::jsonb),
('recipes/lk-gefuellte-kartoffeln-aus-dem-ofen-84218', 'recipes', '{"category": "main", "createdAt": "2026-11-02T21:30:00.000Z", "effort": null, "image": "lk-gefuellte-kartoffeln-aus-dem-ofen-84218", "importId": null, "ingredients": [{"amount": 4, "unit": null, "name": "große vorwiegend festkochende Kartoffeln", "raw": "4 große vorwiegend festkochende Kartoffeln", "foodId": null}, {"amount": 2, "unit": null, "name": "Paprika", "raw": "2 Paprika", "foodId": null}, {"amount": 2, "unit": null, "name": "Lauchzwiebeln", "raw": "2 Lauchzwiebeln", "foodId": null}, {"amount": 0.5, "unit": "Dose", "name": "Mais", "raw": "1/2 Dose Mais", "foodId": null}, {"amount": 200, "unit": "g", "name": "Schmand", "raw": "200 g Schmand", "foodId": null}, {"amount": null, "unit": null, "name": "Salz", "raw": "Salz", "foodId": null}, {"amount": null, "unit": null, "name": "Pfeffer", "raw": "Pfeffer", "foodId": null}, {"amount": null, "unit": null, "name": "Öl", "raw": "Öl", "foodId": null}, {"amount": 200, "unit": "g", "name": "geriebener Gouda", "raw": "200 g geriebener Gouda", "foodId": null}, {"amount": null, "unit": null, "name": "frische gehackte Petersilie zum Garnieren", "raw": "frische gehackte Petersilie zum Garnieren", "foodId": null}], "instructions": "Kartoffeln in Salzwasser bissfest kochen und ausdampfen lassen.\nPaprika und Lauchzwiebeln klein schneiden, mit Mais und Schmand mischen und würzen.\nKartoffeln halbieren und aushöhlen, das Innere unter die Füllung mischen, in eine geölte Form setzen, füllen und mit Käse bestreuen.\nBei 220 °C etwa 20 Minuten backen und mit Petersilie servieren.", "nutrition": {"basis": "portion", "carbs": 43, "fat": 32, "kcal": 539, "protein": 19, "quality": "original"}, "prepMinutes": 50, "servings": 4, "source": "https://www.lecker.de/gefuellte-kartoffeln-aus-dem-ofen-84218.html", "tags": "vegetarisch, kartoffel", "title": "Gefüllte Kartoffeln aus dem Ofen", "titleKey": "gefuellte kartoffeln aus dem ofen", "updatedAt": "2026-11-02T21:30:00.000Z", "version": 1}'::jsonb),
('recipes/lk-kartoffeln-mit-quark-75039', 'recipes', '{"category": "main", "createdAt": "2026-11-02T21:30:00.000Z", "effort": null, "image": "lk-kartoffeln-mit-quark-75039", "importId": null, "ingredients": [{"amount": 1.2, "unit": "kg", "name": "Kartoffeln", "raw": "1,2 kg Kartoffeln", "foodId": null}, {"amount": null, "unit": null, "name": "Salz", "raw": "Salz", "foodId": null}, {"amount": null, "unit": null, "name": "Pfeffer", "raw": "Pfeffer", "foodId": null}, {"amount": null, "unit": null, "name": "Zucker", "raw": "Zucker", "foodId": null}, {"amount": 500, "unit": "g", "name": "Magerquark", "raw": "500 g Magerquark", "foodId": null}, {"amount": 1, "unit": "Bund", "name": "frische Kräuter (z. B. Petersilie, Schnittlauch, Dill)", "raw": "1 Bund frische Kräuter (z. B. Petersilie, Schnittlauch, Dill)", "foodId": null}, {"amount": 1.5, "unit": "TL", "name": "Zitronensaft", "raw": "1,5 TL Zitronensaft", "foodId": null}, {"amount": 2.5, "unit": "EL", "name": "Mineralwasser", "raw": "2,5 EL Mineralwasser", "foodId": null}], "instructions": "Kartoffeln waschen und etwa 20 Minuten in Salzwasser garen.\nKräuter fein hacken und mit Quark, Zitronensaft und Mineralwasser verrühren, mit Salz, Pfeffer und etwas Zucker abschmecken.\nKartoffeln warm pellen und mit dem Kräuterquark servieren.", "nutrition": {"basis": "portion", "carbs": 53, "fat": 0, "kcal": 320, "protein": 23, "quality": "original"}, "prepMinutes": 25, "servings": 4, "source": "https://www.lecker.de/kartoffeln-mit-quark-75039.html", "tags": "vegetarisch, kartoffel, schnell, proteinreich", "title": "Kartoffeln mit Kräuterquark", "titleKey": "kartoffeln mit kraeuterquark", "updatedAt": "2026-11-02T21:30:00.000Z", "version": 1}'::jsonb),
