('recipes/lk-vollkornpasta-advanced-nourishment-74040', 'recipes', '{"category": "main", "createdAt": "2026-11-02T21:30:00.000Z", "effort": null, "image": "lk-vollkornpasta-advanced-nourishment-74040", "importId": null, "ingredients": [{"amount": null, "unit": null, "name": "Salz", "raw": "Salz", "foodId": null}, {"amount": null, "unit": null, "name": "Pfeffer", "raw": "Pfeffer", "foodId": null}, {"amount": 600, "unit": "g", "name": "Möhren", "raw": "600 g Möhren", "foodId": null}, {"amount": 1, "unit": null, "name": "Knoblauchzehe", "raw": "1 Knoblauchzehe", "foodId": null}, {"amount": 1, "unit": "EL", "name": "Olivenöl", "raw": "1 EL Olivenöl", "foodId": null}, {"amount": 500, "unit": "g", "name": "Beefsteakhack", "raw": "500 g Beefsteakhack", "foodId": null}, {"amount": 300, "unit": "g", "name": "Vollkornspaghetti", "raw": "300 g Vollkornspaghetti", "foodId": null}, {"amount": 2, "unit": "EL", "name": "Pinienkerne", "raw": "2 EL Pinienkerne", "foodId": null}, {"amount": 150, "unit": "g", "name": "junger Blattspinat", "raw": "150 g junger Blattspinat", "foodId": null}, {"amount": 150, "unit": "g", "name": "griechischer Sahnejoghurt", "raw": "150 g griechischer Sahnejoghurt", "foodId": null}, {"amount": null, "unit": null, "name": "evtl. Parmesan zum Bestreuen", "raw": "evtl. Parmesan zum Bestreuen", "foodId": null}], "instructions": "Möhren würfeln, Knoblauch hacken. Hack krümelig anbraten, Möhren und Knoblauch kurz mitbraten, würzen und zugedeckt etwa 5 Minuten schmoren.\nNudeln in Salzwasser garen. Pinienkerne ohne Fett rösten, Spinat waschen und trocknen.\nJoghurt unter die Sauce rühren, Nudeln mit dem Spinat untermischen und mit Pinienkernen und nach Wunsch Parmesan servieren.", "nutrition": {"basis": "portion", "carbs": 58, "fat": 19, "kcal": 574, "protein": 42, "quality": "original"}, "prepMinutes": 30, "servings": 4, "source": "https://www.lecker.de/vollkornpasta-advanced-nourishment-74040.html", "tags": "pasta, vollkorn, proteinreich", "title": "Vollkornpa