('recipes/lk-bratreis-mit-gemuese-und-ei-70916', 'recipes', '{"category": "main", "createdAt": "2026-11-02T21:30:00.000Z", "effort": null, "image": "lk-bratreis-mit-gemuese-und-ei-70916", "importId": null, "ingredients": [{"amount": 350, "unit": "g", "name": "Langkornreis", "raw": "350 g Langkornreis", "foodId": null}, {"amount": null, "unit": null, "name": "Salz", "raw": "Salz", "foodId": null}, {"amount": 1, "unit": "Stange", "name": "Porree (Lauch)", "raw": "1 Stange Porree (Lauch)", "foodId": null}, {"amount": 3, "unit": null, "name": "Möhren", "raw": "3 Möhren", "foodId": null}, {"amount": 3, "unit": "Stiel", "name": "Minze oder Koriander", "raw": "3 Stiele Minze oder Koriander", "foodId": null}, {"amount": 250, "unit": "g", "name": "Vollmilchjoghurt", "raw": "250 g Vollmilchjoghurt", "foodId": null}, {"amount": 6, "unit": "EL", "name": "süßscharfe Asiasoße", "raw": "6 EL süßscharfe Asiasoße", "foodId": null}, {"amount": null, "unit": null, "name": "Pfeffer", "raw": "Pfeffer", "foodId": null}, {"amount": 3, "unit": "EL", "name": "Öl", "raw": "3 EL Öl", "foodId": null}, {"amount": 4, "unit": "EL", "name": "Sojasoße", "raw": "4 EL Sojasoße", "foodId": null}, {"amount": 2, "unit": null, "name": "Eier (Gr. M)", "raw": "2 Eier (Gr. M)", "foodId": null}], "instructions": "Reis in Salzwasser garen. Porree in Ringe und Möhren in Scheiben schneiden.\nMinze hacken und mit Joghurt, Asiasoße, Salz und Pfeffer zu einem Dip verrühren.\nPorree und Möhren in Öl anbraten, den Reis zugeben und weiterbraten, mit Sojasoße und Asiasoße würzen.\nEier verquirlen, über den Reis geben und stocken lassen. Mit dem Dip servieren.", "nutrition": {"basis": "portion", "carbs": 85, "fat": 17, "kcal": 564, "protein": 16, "quality": "original"}, "prepMinutes": 30, "servings": 4, "source": "https://www.lecker.de/bratreis-mit-gemuese-und-ei-70916.html", "tags": "vegetarisch, reis", "title": "Bratreis mit Gemüse und Ei", "titleKey": "bratreis mit gemuese und ei", "updatedAt": "2026-11-02T21:30:00.